// These are the raw `elementum_calculated_field.calculation_type` WIRE
// values ei exports — not the authoring-vocabulary names. "HTML" stays here
// unchanged (the platform's wire type for a rich-text calculated field is
// still literally "HTML"); `calculationAuthoringType` is where it's
// translated to the authoring type "RICH_TEXT" for printed source.
export const CALCULATION_RESULT_TYPES = [
    "ATTACHMENT_ID",
    "BOOLEAN",
    "DATE",
    "DATETIME",
    "DECIMAL",
    "GROUP_ID",
    "HANDLE",
    "HTML",
    "JSON",
    "MULTI_PICKLIST",
    "NUMBER",
    "PICKLIST",
    "TEXT",
    "USER_ID",
];
const RESULT_TYPE_SET = new Set(CALCULATION_RESULT_TYPES);
export function isCalculationResultType(value) {
    return typeof value === "string" && RESULT_TYPE_SET.has(value);
}
export function calculationAuthoringType(type) {
    switch (type) {
        case "ATTACHMENT_ID": return "ATTACHMENT";
        case "GROUP_ID": return "GROUP";
        case "USER_ID": return "USER";
        // Wire value is unchanged ("HTML"); the authoring vocabulary is "RICH_TEXT".
        case "HTML": return "RICH_TEXT";
        default: return type;
    }
}
export function calculationExprType(type) {
    switch (type) {
        case "ATTACHMENT_ID": return "attachment";
        case "BOOLEAN": return "bool";
        case "GROUP_ID": return "group";
        case "HANDLE": return "handle";
        case "HTML": return "html";
        case "TEXT": return "text";
        case "MULTI_PICKLIST": return "multiPicklist";
        case "PICKLIST": return "picklist";
        case "USER_ID": return "user";
        default: return type.toLowerCase();
    }
}
